package com.campus.lostfound.service;
import com.campus.lostfound.model.*; import com.campus.lostfound.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ItemService { private final ItemRepository items; private final MatchService matcher; private final AuditLogRepository logs; public ItemService(ItemRepository i,MatchService m,AuditLogRepository l){items=i;matcher=m;logs=l;}
 public List<Item> browse(String q,String type,String category,String location,String status){return items.findAllByOrderBySubmittedAtDesc().stream().filter(i->q==null||q.isBlank()||i.getItemName().toLowerCase().contains(q.toLowerCase())||(i.getLocation()!=null&&i.getLocation().toLowerCase().contains(q.toLowerCase()))).filter(i->type==null||type.isBlank()||i.getReportType().equals(type)).filter(i->category==null||category.isBlank()||i.getCategory().name().equals(category)).filter(i->location==null||location.isBlank()||(i.getLocation()!=null&&i.getLocation().equalsIgnoreCase(location))).filter(i->status==null||status.isBlank()||i.getStatus().name().equals(status)).toList();}
 @Transactional public Item save(Item i,User actor){Item saved=items.save(i);logs.save(new AuditLog("REPORT_CREATED",i.getReportType()+" #"+saved.getId(),actor));return saved;} public Optional<Item> find(Long id){return items.findById(id);} public List<Item> mine(User u){return items.findByReporterOrderBySubmittedAtDesc(u);} public List<Item> matches(Item i){return matcher.findMatches(i,items.findAll());}
 @Transactional public void close(Item i,User admin){i.setStatus(ReportStatus.CLOSED);items.save(i);logs.save(new AuditLog("REPORT_CLOSED","Item #"+i.getId(),admin));}
 @Transactional public void remove(Item i,User admin){logs.save(new AuditLog("REPORT_REMOVED","Item #"+i.getId(),admin));items.delete(i);}
}
